    demo_data = json.load(f)

demo_input = demo_data[0]['input']
demo_output = demo_data[0]['output']

def find_boxes(grid):
    """Find all rectangular box outlines in grid. Returns list of (r1, c1, r2, c2, color)"""
    arr = np.array(grid)
    h, w = arr.shape
    boxes = []

    # For each possible box size
    for r1 in range(h):
        for c1 in range(w):
            for r2 in range(r1 + 3, min(h, r1 + 12)):
                for c2 in range(c1 + 3, min(w, c1 + 12)):
                    # Check if this forms a box of a single color
                    color = arr[r1, c1]

                    # Skip if it's a uniform fill (no hole) or empty
                    if arr[r1, c2] != color or arr[r2, c1] != color or arr[r2, c2] != color:
                        continue

                    # Check all border cells
                    is_box = True
                    for col in range(c1, c2 + 1):
                        if arr[r1, col] != color or arr[r2, col] != color:
                            is_box = False
                            break
                    if not is_box:
                        continue
                    for row in range(r1, r2 + 1):
                        if arr[row, c1] != color or arr[row, c2] != color:
                            is_box = False
                            break
                    if not is_box:
                        continue

                    # Check interior exists and is uniform
                    interior = arr[r1+1:r2, c1+1:c2]
                    if len(set(interior.ravel())) == 1:
                        boxes.append((r1, c1, r2, c2, color))

    return boxes

def transform_with_boxes(grid, boxes):
    """Apply transformation: 2x2 interior -> 2, everything else -> 7"""
    arr = np.array(grid)
    h, w = arr.shape
    output = arr.copy()

    # Sort boxes by size (larger first) so smaller boxes in interiors still get processed
    sorted_boxes = sorted(boxes, key=lambda b: (b[2] - b[0]) * (b[3] - b[1]), reverse=True)

    for r1, c1, r2, c2, color in sorted_boxes:
        r_start_i = r1 + 1
        r_end_i = r2 - 1
        c_start_i = c1 + 1
        c_end_i = c2 - 1

        if r_start_i > r_end_i or c_start_i > c_end_i:
            continue

        interior_h = r_end_i - r_start_i + 1
        interior_w = c_end_i - c_start_i + 1

        if interior_h == 2 and interior_w == 2:
            fill_val = 2
        else:
            fill_val = 7

        output[r_start_i:r_end_i+1, c_start_i:c_end_i+1] = fill_val

    return output.tolist()

# Test
