print(f"Found {len(boxes)} boxes")
for b in boxes:
    r1, c1, r2, c2, color = b
    interior_h = r2 - r1 - 1
    interior_w = c2 - c1 - 1
    print(f"  Box at ({r1},{c1})-({r2},{c2}), color={color}, interior={interior_h}x{interior_w}")

